    var zt = modelContainer.getValue("zt");
    //如果单据状态为已发布
    if(zt == "7"){
        FormButton2.setVisible(false);//编辑
        FormButton1.setVisible(false);//保存
        FormButton3.setDisabled(true);//发布
        FormButton4.setDisabled(false);//撤回
    }else if(zt == "8"){
        //如果单据状态为已撤回
        FormButton3.setDisabled(false);//发布
        FormButton4.setDisabled(true);//撤回
    }else if(zt == "0"){
        //如果单据状态为编辑中
        FormButton3.setDisabled(true);//发布
        FormButton4.setDisabled(true);//撤回
        FormButton1.setDisabled(true);//保存
    }else{
        //如果单据状态为已归档
        FormButton2.setVisible(false);//编辑
        FormButton1.setVisible(false);//保存
        FormButton3.setVisible(false);//发布
